import{_ as s,a0 as i,w as a,s as l,ao as d,I as e,x as o,a1 as p,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"安卓編年史（16）：安卓 3.0 蜂巢—平板和設計復興 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（16）：安卓 3.0 蜂巢—平板和設計復興 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（16）：安卓 3.0 蜂巢—平板和設計復興 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（16）：安卓 3.0 蜂巢—平板和設計復興 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/18 - The history of Android","title":"安卓編年史（16）：安卓 3.0 蜂巢—平板和設計復興","tag":"The history of Android","desc":""},"relativePath":"The history of Android/18 - The history of Android.md","filePath":"[post].md"}'),m={name:"The history of Android/18 - The history of Android.md"};function u(g,t,h,f,T,A){const n=i("Link");return a(),l("div",null,[t[20]||(t[20]=d('<h1 id="安卓編年史-16-安卓-3-0-蜂巢—平板和設計復興" tabindex="-1">安卓編年史（16）：安卓 3.0 蜂巢—平板和設計復興 <a class="header-anchor" href="#安卓編年史-16-安卓-3-0-蜂巢—平板和設計復興" aria-label="Permalink to “安卓編年史（16）：安卓 3.0 蜂巢—平板和設計復興”">​</a></h1><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/play-store.png" alt="安卓市場的新設計試水“卡片式”界面，這將成為谷歌的主要風格。"></p><p><em>安卓市場的新設計試水“卡片式”界面，這將成為谷歌的主要風格。 [Ron Amadeo 供圖]</em></p><p>安卓推向市場已經有兩年半時間了，安卓市場放出了它的第四版設計。這個新設計十分重要，因為它已經很接近谷歌的“卡片式”界面了。通過在小方塊中顯示應用或其他內容，谷歌可以使它的設計在不同尺寸屏幕下無縫過渡而不受影響。內容可以像一個相冊應用裏的照片一樣顯示——給佈局渲染填充一個內容塊列表，加上屏幕包裝，就完成了。更大的屏幕一次可以看到更多的內容塊，小點的屏幕一次看到的內容就少。內容用了不一樣的方式顯示，谷歌還在右邊新增了一個“分類”板塊，頂部還有個巨大的熱門應用滾動顯示。</p><p>雖然設計上為更容易配置界面準備好準備好了，但功能上還沒有。最初發布的市場版本鎖定為橫屏模式，而且還是蜂巢獨佔的。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/device-2014-02-12-190002.png" alt="應用詳情頁和“我的應用”界面。"></p><p><em>應用詳情頁和“我的應用”界面。 [Ron Amadeo 供圖]</em></p><p>新的市場不僅出售應用，還加入了書籍和電影租借。谷歌從 2010 年開始出售圖書；之前只通過網站出售。新的市場將谷歌所有的內容銷售聚合到了一處，進一步向蘋果 iTunes 所的主宰地位展開較量。雖然在“安卓市場”出售這些東西有點品牌混亂，因為大部分內容都不依賴於安卓才能使用。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/browsercontactst.png" alt="瀏覽器看起來非常像 Chrome，聯繫人使用了雙面板界面。"></p><p><em>瀏覽器看起來非常像 Chrome，聯繫人使用了雙面板界面。 [Ron Amadeo 供圖]</em></p><p>新瀏覽器界面頂部添加了標籤頁欄。儘管這個瀏覽器並不是 Chrome ，但它模仿了許多 Chrome 的設計和特性。除了這個探索性的頂部標籤頁界面，瀏覽器還加入了隱身標籤，在瀏覽網頁時不保存歷史記錄和自動補全記錄。它還有個選項可以讓你擁有一個 Chrome 風格的新標籤頁，頁面上包含你最經常訪問的網頁略縮圖。</p><p>新瀏覽器甚至還能和 Chrome 同步。在瀏覽器登錄後，它會下載你的 Chrome 書籤並且自動登錄你的谷歌賬户。收藏一個頁面只需點擊地址欄的星形標誌即可，和谷歌地圖一樣，瀏覽器拋棄了縮放按鈕，完全改用手勢控制。</p><p>聯繫人應用最終從電話應用中移除，並且獨立為一個應用。之前的聯繫人/撥號的混合式設計相對於人們使用現代智能手機的方式來説，過於以電話為中心了。聯繫人中存有電子郵件、IM、短信、地址、生日以及社交網絡等信息，所以將它們捆綁在電話應用裏的意義和將它們放進谷歌地圖裏差不多。拋開了電話通訊功能，聯繫人能夠簡化成沒有標籤頁的聯繫人列表。蜂巢採用了雙面板視圖，在左側顯示完整的聯繫人列表，右側是聯繫人詳情。應用利用了 Fragments API，通過它應用可以在同一屏顯示多個面板界面。</p><p>蜂巢版本的聯繫人應用是第一個擁有快速滾動功能的版本。當按住左側滾動條的時候，你可以快速上下拖動，應用會顯示列表當前位置的首字母預覽。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/youtubes.png" alt="新 Youtube 應用看起來像是來自黑客帝國。"></p><p><em>新 Youtube 應用看起來像是來自黑客帝國。 [Ron Amadeo 供圖]</em></p><p>謝天謝地 Youtube 終於拋棄了自安卓 2.3 以來的谷歌給予這個視頻服務的“獨特”設計，新界面設計與系統更加一體化。主界面是一個水平滾動的曲面牆，上面顯示着最熱門或者（登錄之後）個人關注的視頻。雖然谷歌從來沒有將這個設計帶到手機上，但它可以被認為是一個易於重新配置的卡片界面。操作欄在這裏是個可配置的工具欄。沒有登錄時，操作欄由一個搜索欄填滿。當你登錄後，搜索縮小為一個按鈕，“首頁”，“瀏覽”和“你的頻道”標籤將會顯示出來。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/other2.png" alt="蜂巢用一個藍色框架的電腦界面來驅動主屏。電影工作室完全採用橙色電子風格主題。"></p><p><em>蜂巢用一個藍色框架的電腦界面來驅動主屏。電影工作室完全採用橙色電子風格主題。 [Ron Amadeo 供圖]</em></p><p>蜂巢新增的應用“電影工作室”，這不是一個不言自明的應用，而且沒有任何的解釋或説明。就我們所知，你可以導入視頻，剪切它們，添加文本和場景過渡。編輯視頻——電腦上你可以做的最耗時、困難，以及處理器密集型任務之一 —— 在平板上完成感覺有點野心過大了，谷歌在之後的版本里將其完全移除了。電影工作室裏我們最喜歡的部分是它完全的電子風格主題。雖然系統的其它部分使用藍色高亮，在這裏是橙色的。（電影工作室是個邪惡的程序！）</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/device-2014-02-12-202224.png" alt="小部件！"><em>小部件！ [Ron Amadeo 供圖]</em></p><p>蜂巢帶來了新的部件框架，允許部件滾動，Gmail、Email 以及日曆部件都升級了以支持改功能。Youtube 和書籍使用了新的部件，內容卡片可以自動滾動切換。在小部件上輕輕向上或向下滑動可以切換卡片。我們不確定你的書籍中哪些書會被顯示出來，但如果你想要的話它就在那兒。儘管所有的這些小部件在 10 英寸屏幕上運行良好，谷歌從未為手機重新設計它們，這讓它們在安卓最流行的規格上幾乎毫無用處。所有的小部件有個大塊的標識標題欄，而且通常佔據大半屏幕只顯示很少的內容。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/31new.jpg" alt="安卓3.1中可滾動的最近應用以及可自定義大小的小部件。"></p><p><em>安卓 3.1 中可滾動的最近應用以及可自定義大小的小部件。 [Ron Amadeo 供圖]</em></p><p>蜂巢後續的版本修復了 3.0 早期的一些問題。安卓 3.1 在蜂巢的第一個版本之後三個月放出，並帶來了一些改進。小部件自定義大小是添加的最大特性之一。長按小部件之後，一個帶有拖拽按鈕的藍色外框會顯示出來，拖動按鈕可以改變小部件尺寸。最近應用界面現在可以垂直滾動並且承載更多應用。這個版本唯一缺失的功能是滑動關閉應用。</p><p>在今天，一個 0.1 版本的升級是個主要更新，但是在蜂巢，那只是個小更新。除了一些界面調整，3.1 添加了對遊戲手柄，鍵盤，鼠標以及其它 USB 和藍牙輸入設備的支持。它還提供了更多的開發者 API。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/device-2014-02-14-131132.jpg" alt="安卓3.2的兼容性縮放和一個安卓平板上典型的展開視圖應用。"></p><p><em>安卓 3.2 的兼容性縮放和一個安卓平板上典型的展開視圖應用。 [Ron Amadeo 供圖]</em></p><p>安卓 3.2 在 3.1 發佈後兩個月放出，添加了七到八英寸的小尺寸平板支持。3.2 終於啓用了 SD 卡支持，Xoom 在生命最初的五個月就像是初生兒的柔弱的肢體一樣。</p><p>蜂巢匆匆問世是為了成為一個生態系統建設者。如果應用沒有平板版本，沒人會想要一個安卓平板的，所以谷歌知道需要儘快將東西送到開發者手中。在這個安卓平板生態的早期階段，應用還沒有到齊。這是擁有 Xoom 的人們所面臨的最大的問題。</p>',30)),e("p",null,[t[1]||(t[1]=o("3.2 添加了“兼容縮放”，給了用户一個新選項，可以將應用拉伸適應屏幕（如右側圖片顯示的那樣）或縮放成正常的應用佈局來適應屏幕。這些選項都不是很理想，由於沒有應用生態來支持平板，蜂巢設備銷售狀況慘淡。但谷歌的平板決策最終還是會得到回報。今天，安卓平板已經",-1)),p(n,{href:"http://techcrunch.com/2014/03/03/gartner-195m-tablets-sold-in-2013-android-grabs-top-spot-from-ipad-with-62-share/"},{default:r(()=>[...t[0]||(t[0]=[o("取代 iOS 佔據了最大的市場份額",-1)])]),_:1}),t[2]||(t[2]=o("。",-1))]),t[21]||(t[21]=e("p",null,[e("img",{src:"http://cdn.arstechnica.net/wp-content/uploads/2014/03/device-2014-03-31-110613.png",alt:"薑餅上的 Google Music Beta。"})],-1)),t[22]||(t[22]=e("p",null,[e("em",null,"薑餅上的 Google Music Beta。 [Ron Amadeo 供圖]")],-1)),t[23]||(t[23]=e("h3",{id:"google-music-beta-——-取代內容商店的雲存儲",tabindex:"-1"},[o("Google Music Beta —— 取代內容商店的雲存儲 "),e("a",{class:"header-anchor",href:"#google-music-beta-——-取代內容商店的雲存儲","aria-label":"Permalink to “Google Music Beta —— 取代內容商店的雲存儲”"},"​")],-1)),e("p",null,[t[4]||(t[4]=o("儘管蜂巢改進了 Google Music 的界面，但是音樂應用的設計並沒有從蜂巢直接進化到冰淇淋三明治。2011 年 5 月，谷歌發佈了“",-1)),p(n,{href:"http://techcrunch.com/2014/03/03/gartner-195m-tablets-sold-in-2013-android-grabs-top-spot-from-ipad-with-62-share/"},{default:r(()=>[...t[3]||(t[3]=[o("Google Music Beta",-1)])]),_:1}),t[5]||(t[5]=o("”，和新的 Google Music 應用一同到來的在線音樂存儲。",-1))]),t[24]||(t[24]=e("p",null,"新 Google Music 為安卓 2.2 及以上版本設計，借鑑了 Cooliris 相冊的設計語言，但也有改變之處，背景使用了模糊處理的圖片。幾乎所有東西都是透明的：彈出菜單，頂部標籤頁，還有底部的正在播放欄。可以下載單獨的歌曲或整個播放列表到設備上離線播放，這讓 Google Music 成為一個讓音樂同步到你所有設備的好途徑。除了移動應用外，Google Music 還有一個 Web 應用，讓它可以在任何一台桌面電腦上使用。",-1)),t[25]||(t[25]=e("p",null,"谷歌和唱片公司關於內容的合約還沒有談妥，音樂商店還沒準備好，所以它的權宜之計是允許用户存儲音樂到線上並下載到設備上。如今谷歌除了音樂存儲服務外，還有單曲購買和訂閲模式。",-1)),t[26]||(t[26]=e("hr",null,null,-1)),t[27]||(t[27]=e("p",null,[e("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2016/05/r.amadeo-45843.jpg",alt:"Ron Amadeo"})],-1)),e("p",null,[p(n,{href:"http://arstechnica.com/author/ronamadeo"},{default:r(()=>[...t[6]||(t[6]=[o("Ron Amadeo",-1)])]),_:1}),t[8]||(t[8]=o(" / Ron 是 Ars Technica 的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1)),p(n,{href:"https://twitter.com/RonAmadeo"},{default:r(()=>[...t[7]||(t[7]=[o("@RonAmadeo",-1)])]),_:1})]),t[28]||(t[28]=e("hr",null,null,-1)),e("p",null,[t[10]||(t[10]=o("via: ",-1)),p(n,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/18/"},{default:r(()=>[...t[9]||(t[9]=[o("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/18/",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=o("譯者：",-1)),p(n,{href:"https://github.com/alim0x"},{default:r(()=>[...t[11]||(t[11]=[o("alim0x",-1)])]),_:1}),t[14]||(t[14]=o(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[12]||(t[12]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[17]||(t[17]=o("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[15]||(t[15]=[o("LCTT",-1)])]),_:1}),t[18]||(t[18]=o(" 原創翻譯，",-1)),p(n,{href:"http://linux.cn/"},{default:r(()=>[...t[16]||(t[16]=[o("Linux中國",-1)])]),_:1}),t[19]||(t[19]=o(" 榮譽推出",-1))])])}const x=s(m,[["render",u]]);export{w as __pageData,x as default};
